package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class OperationOverviewDialog {
 static AlertDialog show(MainActivity owner){LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(24,12,24,12);TextView content=new TextView(owner);box.addView(content);Button refresh=new Button(owner);refresh.setText("状態を更新");box.addView(refresh);Button check=new Button(owner);check.setText("スマホのローカル動作チェックを実行");box.addView(check);Button report=new Button(owner);report.setText("個人情報を除いた不具合報告");box.addView(report);report.setOnClickListener(v->{report.setEnabled(false);new Thread(()->{String value;try{value=PublicDiagnosticReport.build(OperationOverview.read(owner)).toString(2);}catch(Exception error){value="診断記録を作成できませんでした。自動送信はしていません。";}final String text=value;owner.runOnUiThread(()->{report.setEnabled(true);if(!owner.isDestroyed())new AlertDialog.Builder(owner).setTitle("不具合報告（自動送信しません）").setMessage(text+"\n会話本文・認識文・場所・予定名・ID・生のエラー・認証情報を含めません。").setPositiveButton("コピー",(d,w)->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)owner.getSystemService(android.content.Context.CLIPBOARD_SERVICE);clipboard.setPrimaryClip(android.content.ClipData.newPlainText("ロキ診断",text));}).setNegativeButton("閉じる",null).show();});},"PublicDiagnostic").start();});ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("依頼・転送・動作チェック").setView(scroll).setPositiveButton("閉じる",null).create();Runnable load=()->{refresh.setEnabled(false);new Thread(()->{String value;try{value=describe(OperationOverview.read(owner));}catch(Exception e){value="状態を取得できませんでした。依頼の再送はしていません。";}final String result=value;owner.runOnUiThread(()->{refresh.setEnabled(true);if(dialog.isShowing())content.setText(result);});},"OperationOverview").start();};refresh.setOnClickListener(v->load.run());check.setOnClickListener(v->{LocalHealthCheck.start(owner,true);content.setText("検査中です。しばらくして状態を更新してください。外部送信・撮影・録音は行いません。");});dialog.show();load.run();return dialog;}
 static String describe(JSONObject data){StringBuilder text=new StringBuilder(data.optString("connection")+"\n\n"+AssistantActivityState.describe(data.optJSONObject("activity"),data.optBoolean("transferStateFresh"))+"\n\n未完了の会話を優先し、ID付き会話依頼・保留案件と直近の端末操作を表示します。結果未確認を再送していません。\n");if(data.optJSONArray("issues")!=null&&data.optJSONArray("issues").length()>0)text.append("\n一部の保存記録を読み取れませんでした。読み取れる診断結果を表示します。自動修復・再送はしていません。\n");JSONArray cards=data.optJSONArray("cards");if(cards!=null)for(int i=0;i<cards.length();i++){JSONObject row=cards.optJSONObject(i);text.append("\n").append(row.optString("label")).append("：").append(row.optString("title")).append("\nID ").append(row.optString("id").substring(0,Math.min(8,row.optString("id").length()))).append("\n");if(!row.optString("detail").isEmpty())text.append(row.optString("detail")).append("\n");}JSONObject storage=data.optJSONObject("storage");if(storage!=null)text.append("\n\n").append(storage.optBoolean("unavailable")?"保存先の在庫を確認できませんでした":StorageCheckpoint.describe(storage));text.append("\n転送：").append(data.optBoolean("transferStateFresh")?"最近のグラス状態":"グラスの状態が古い可能性があります");JSONArray transfers=data.optJSONArray("transfers");if(transfers!=null)for(int i=0;i<transfers.length();i++)text.append("\n").append(TransferProgressPolicy.label(transfers.optJSONObject(i)));if(transfers==null||transfers.length()==0)text.append("\nまだ転送結果は届いていません。スマホの保存数だけではグラスに残る件数を判断できません。");text.append("\n\nスマホ\n").append(LocalHealthCheck.describe(data.optJSONObject("phoneHealth")==null?new JSONObject():data.optJSONObject("phoneHealth"))).append("\n\nグラス\n").append(LocalHealthCheck.describe(data.optJSONObject("glassHealth")==null?new JSONObject():data.optJSONObject("glassHealth")));return text.toString();}
 private OperationOverviewDialog(){}
}